import urllib.request
from Bio.PDB import PDBParser, Superimposer
ref_path = outdir+"/1mso.pdb"
urllib.request.urlretrieve("https://files.rcsb.org/download/1MSO.pdb", ref_path)
ref = PDBParser(QUIET=True).get_structure("r", ref_path)[0]
lines = ["1MSO chains: " + str([c.id for c in ref])]

def getca(stru, chain, i):
    try:
        r = stru[chain][i]
    except KeyError:
        return None
    return r["CA"] if r.has_id("CA") else None

fixed, moving, used = [], [], []
for ch, L in [("A",21), ("B",30)]:
    for i in range(1, L+1):
        a = getca(ref, ch, i); b = getca(st, ch, i)
        if a is not None and b is not None:
            fixed.append(a); moving.append(b); used.append((ch,i))
lines.append("CA pairs used: %d" % len(fixed))
sup = Superimposer(); sup.set_atoms(fixed, moving)
lines.append("Full complex (A+B) CA RMSD vs 1MSO: %.2f A" % sup.rms)

for ch, L in [("A",21), ("B",30)]:
    f, m = [], []
    for i in range(1, L+1):
        a = getca(ref, ch, i); b = getca(st, ch, i)
        if a is not None and b is not None:
            f.append(a); m.append(b)
    s2 = Superimposer(); s2.set_atoms(f, m)
    lines.append("  chain %s alone (%d CA): %.2f A" % (ch, len(f), s2.rms))

# B-chain central helix B9-B19 + A chain, the structured core
f, m = [], []
for ch, rng in [("A", range(1,22)), ("B", range(9,20))]:
    for i in rng:
        a = getca(ref, ch, i); b = getca(st, ch, i)
        if a is not None and b is not None:
            f.append(a); m.append(b)
s3 = Superimposer(); s3.set_atoms(f, m)
lines.append("  core (A1-A21 + B9-B19, %d CA): %.2f A" % (len(f), s3.rms))
print("\n".join(lines))
